entries[203376] = { ["name"] = "Anhängerin: Emmarel Schattenwächter", ["text"] = "Sofort\nEmmarel Schattenwächter war eine junge Schildwache, als der Unsichtbare Pfad gegründet wurde. Wie ihre Mentorin, Namuria Hainsang, glaubte Emmarel, dass es die Pflicht der Nachtelfen sei, Azeroth vor der unvermeidlichen Rückkehr der Legion zu schützen. Nachdem ihr Orden im Krieg der Sandstürme beinahe vernichtet worden war, führte Emmarel ihn als kleine und verborgene Gruppe weiter, stets in Erwartung des Tages, an dem er wiederauferstehen sollte.0[Quellwert] In den vielen Jahren der Wache studierte Emmarel die Kunst der Tierherrschaft. Sie ist nie weit von den Federspitzen ihres geliebten Adlerbegleiters Schneefeder entfernt.", ["unresolvedValues"] = true }
